-- Journal entries: one row per visit a user logs at a building.
--
-- The diary is strictly private. Row-level security lets each signed-in user
-- see and change only their own rows, and nothing is readable signed out.
-- The checks mirror the form's limits in src/journal/types.ts, so a modified
-- client can't store anything the app wouldn't allow.

create table public.entries (
  -- Generated by the client (crypto.randomUUID), so entries can be shown before the insert returns.
  id          uuid primary key default gen_random_uuid(),
  user_id     uuid not null default auth.uid() references auth.users (id) on delete cascade,
  -- A permanent slug from src/data/campusMap.ts, e.g. "bobst-library".
  building_id text not null check (building_id ~ '^[a-z0-9]+(-[a-z0-9]+)*$' and char_length(building_id) <= 100),
  -- One day of grace past the server's date for users in timezones ahead of UTC.
  visited_on  date not null check (visited_on >= date '1900-01-01' and visited_on <= current_date + 1),
  -- char_length counts characters, like the client's Array.from(text).length.
  floor       text not null default '' check (char_length(floor) <= 3),
  -- 0 means unrated; otherwise 0.5 to 5 in half steps.
  rating      numeric(2, 1) not null default 0 check (rating between 0 and 5 and rating * 2 = trunc(rating * 2)),
  notes       text not null default '' check (char_length(notes) <= 200),
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now()
);

comment on table public.entries is 'Private journal entries; each user can only access their own.';

-- The diary lists a user's entries newest first; a building's log filters that by building.
create index entries_user_newest_idx on public.entries (user_id, visited_on desc, created_at desc);
create index entries_user_building_idx on public.entries (user_id, building_id);

-- Keep owner and creation time fixed on update, and stamp updated_at.
create function public.entries_before_update()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  new.user_id := old.user_id;
  new.created_at := old.created_at;
  new.updated_at := now();
  return new;
end;
$$;

create trigger entries_before_update
before update on public.entries
for each row execute function public.entries_before_update();

-- Row-level security: owner-only access.
alter table public.entries enable row level security;

-- Signed-out visitors get no access at all, not even an empty result.
revoke all on public.entries from anon;
grant select, insert, update, delete on public.entries to authenticated;

-- (select auth.uid()) is evaluated once per query rather than once per row.
create policy "Users can read their own entries"
  on public.entries for select to authenticated
  using (user_id = (select auth.uid()));

create policy "Users can add their own entries"
  on public.entries for insert to authenticated
  with check (user_id = (select auth.uid()));

create policy "Users can edit their own entries"
  on public.entries for update to authenticated
  using (user_id = (select auth.uid()))
  with check (user_id = (select auth.uid()));

create policy "Users can delete their own entries"
  on public.entries for delete to authenticated
  using (user_id = (select auth.uid()));
